using namespace std;
using int64 = long long;
// a 全是非负数，返回和 <= k 的最长子数组长度
int longest_le(const vector<int64> &a, int64 k) {
    int left = 0, best = 0;
    int64 cur = 0;
    for (int right = 0; right < (int)a.size(); ++right) {
        cur += a[right];
        while (cur > k && left <= right) {
            cur -= a[left];
            ++left;
        }
        best = max(best, right - left + 1);
    }
    return best;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    int64 k;
    if (!(cin >> n >> k)) return 0;
    vector<int64> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    cout << longest_le(a, k) << '\n';
    return 0;
}

