from collections import deque


def sliding_max(a, k):
    '''返回每个长度为 k 的滑动窗口的最大值。'''
    dq = deque()
    res = []
    for i, v in enumerate(a):
        while dq and a[dq[-1]] <= v:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            res.append(a[dq[0]])
    return res


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, k = data[0], data[1]
    a = data[2:2 + n]
    print(' '.join(map(str, sliding_max(a, k))))

