struct Node { int val; Node *next; Node(int v): val(v), next(nullptr) {} };
// 快慢指针判环
bool has_cycle(Node *head) {
    Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}
