        Node *nd = new Node(v);
        if (!head) head = nd; else tail->next = nd;
        tail = nd;
    }
    Node *cur = reverse_list(head);
    bool first = true;
    while (cur) {
        if (!first) cout << ' ';
        cout << cur->val;
        first = false;
        cur = cur->next;
    }
