def count_islands(grid):
    ''''1' 为陆地，四连通，求岛屿数量。'''
    n, m = len(grid), len(grid[0])
    seen = [[False] * m for _ in range(n)]

    def flood(x, y):
        seen[x][y] = True
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == 1 and not seen[nx][ny]:
                flood(nx, ny)

    cnt = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not seen[i][j]:
                flood(i, j)
                cnt += 1
    return cnt


