#include <bits/stdc++.h>
using namespace std;
// 节点 1..n，边 (u,v) 表 u 在 v 之前；无环返回 true
bool can_finish(int n, const vector<pair<int,int>> &edges) {
    vector<vector<int>> g(n + 1);
    vector<int> indeg(n + 1, 0);
    for (auto [u, v] : edges) { g[u].push_back(v); ++indeg[v]; }
    queue<int> q;
    for (int i = 1; i <= n; ++i) if (indeg[i] == 0) q.push(i);
    int done = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        ++done;
        for (int w : g[u]) if (--indeg[w] == 0) q.push(w);
    }
    return done == n;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<pair<int,int>> edges(m);
    for (int i = 0; i < m; ++i) cin >> edges[i].first >> edges[i].second;
    cout << (can_finish(n, edges) ? "YES\n" : "NO\n");
    return 0;
}

