#include <bits/stdc++.h>
using namespace std;
struct DSU {
    vector<int> fa, rank_;
    DSU(int n = 0) { fa.resize(n + 1); rank_.assign(n + 1, 0); iota(fa.begin(), fa.end(), 0); }
    int find(int x) {
        while (fa[x] != x) { fa[x] = fa[fa[x]]; x = fa[x]; }
        return x;
    }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (rank_[ra] < rank_[rb]) swap(ra, rb);
        fa[rb] = ra;
        if (rank_[ra] == rank_[rb]) ++rank_[ra];
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    DSU dsu(n);
    for (int i = 0; i < m; ++i) { int u, v; cin >> u >> v; dsu.unite(u, v); }
    int cnt = 0;
    for (int i = 1; i <= n; ++i) if (dsu.find(i) == i) ++cnt;
    cout << cnt << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int64 INF = (int64)4e18;
// 边权非负，返回 s 到各点最短路（1-based，不可达 -1）
vector<int64> dijkstra(int n, const vector<tuple<int,int,int64>> &edges, int s) {
    vector<vector<pair<int,int64>>> g(n + 1);
    for (auto [u, v, w] : edges) g[u].push_back({v, w});
    vector<int64> dist(n + 1, INF);
    dist[s] = 0;
    priority_queue<pair<int64,int>, vector<pair<int64,int>>, greater<pair<int64,int>>> pq;
    pq.push({0, s});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : g[u]) if (d + w < dist[v]) {
            dist[v] = d + w;
            pq.push({dist[v], v});
        }
    }
    vector<int64> res;
    for (int i = 1; i <= n; ++i) res.push_back(dist[i] == INF ? -1 : dist[i]);
    return res;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, s;
    if (!(cin >> n >> m >> s)) return 0;
    vector<tuple<int,int,int64>> edges;
    for (int i = 0; i < m; ++i) { int u, v; int64 w; cin >> u >> v >> w; edges.push_back({u, v, w}); }
    auto r = dijkstra(n, edges, s);
    for (int i = 0; i < n; ++i) cout << r[i] << (i + 1 == n ? '\n' : ' ');
    return 0;
}

