def bellman_ford(n, edges, s):
    '''允许负权（假定从 s 可达范围内无负环），返回最短路，不可达为 -1。'''
    dist = [INF] * (n + 1)
    dist[s] = 0
    for _ in range(n - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break
    return [-1 if dist[i] == INF else dist[i] for i in range(1, n + 1)]


