vector<vector<int64>> floyd(int n, const vector<tuple<int,int,int64>> &edges) {
    vector<vector<int64>> d(n, vector<int64>(n, INF));
    for (int i = 0; i < n; ++i) d[i][i] = 0;
    for (auto [u, v, w] : edges) d[u][v] = min(d[u][v], w);
