using namespace std;
using int64 = long long;
// 0/1 背包：一维 DP 倒序
int64 knapsack_01(int W, const vector<pair<int,int64>> &items) {
    vector<int64> dp(W + 1, 0);
    for (auto [w, v] : items)
        for (int c = W; c >= w; --c)
            dp[c] = max(dp[c], dp[c - w] + v);
    return dp[W];
}
