def knapsack_complete(n, W, items):
    '''完全背包：每种物品无限件，容量 W，求最大价值。一维 DP 正序。'''
    dp = [0] * (W + 1)
    for w, v in items:
        for c in range(w, W + 1):
            if dp[c - w] + v > dp[c]:
                dp[c] = dp[c - w] + v
