    vector<tuple<int,int,int64>> edges;
    for (int i = 0; i < m; ++i) { int u, v; int64 w; cin >> u >> v >> w; edges.push_back({u, v, w}); }
    cout << mst(n, edges) << '\n';
    return 0;
}

