def kmp_search(text, pat):
    '''返回 pat 在 text 中所有出现位置的起始下标（0-based）。'''
    if not pat:
        return []
    m = len(pat)
    pi = [0] * m
    for i in range(1, m):
        j = pi[i - 1]
        while j > 0 and pat[i] != pat[j]:
            j = pi[j - 1]
        if pat[i] == pat[j]:
            j += 1
        pi[i] = j
    res = []
    j = 0
    for i, ch in enumerate(text):
        while j > 0 and ch != pat[j]:
            j = pi[j - 1]
        if ch == pat[j]:
            j += 1
        if j == m:
            res.append(i - m + 1)
            j = pi[j - 1]
    return res


if __name__ == '__main__':
    import sys
    lines = sys.stdin.read().split('\n')
    text = lines[0] if len(lines) > 0 else ''
    pat = lines[1] if len(lines) > 1 else ''
    print(' '.join(map(str, kmp_search(text, pat))))

