class TrieNode:
    def __init__(self):
        self.child = {}
        self.is_end = False


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.child.setdefault(ch, TrieNode())
        node.is_end = True

    def search(self, word):
        node = self.root
        for ch in word:
            node = node.child.get(ch)
            if node is None:
                return False
        return node.is_end

    def starts_with(self, prefix):
        node = self.root
        for ch in prefix:
            node = node.child.get(ch)
            if node is None:
                return False
        return True


if __name__ == '__main__':
    import sys
    lines = sys.stdin.read().strip().split('\n')
    q = int(lines[0]) if lines and lines[0] else 0
    trie = Trie()
    out = []
    for i in range(1, q + 1):
        parts = lines[i].split()
        op, word = parts[0], parts[1] if len(parts) > 1 else ''
        if op == '1':
            trie.insert(word)
        elif op == '2':
            out.append('YES' if trie.search(word) else 'NO')
        elif op == '3':
            out.append('YES' if trie.starts_with(word) else 'NO')
    sys.stdout.write('\n'.join(out))

