using namespace std;
using int64 = long long;
using i128 = __int128_t;
// (a*b) % mod，a、b 可达 1e18，用 __int128 防溢出
int64 mod_mul(int64 a, int64 b, int64 mod) {
    return (int64)((i128)(a % mod) * (b % mod) % mod);
}
// 整数平方根（向下取整），中点防溢出写法
int64 isqrt_ll(int64 n) {
    if (n < 2) return n;
    int64 lo = 1, hi = n / 2;
    while (lo <= hi) {
        int64 mid = lo + (hi - lo) / 2;
        i128 sq = (i128)mid * mid;
        if (sq == n) return mid;
        if (sq < n) lo = mid + 1;
        else hi = mid - 1;
    }
    return hi;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    if (!(cin >> q)) return 0;
    for (int i = 0; i < q; ++i) {
        int64 a, b, m;
        cin >> a >> b >> m;
        cout << mod_mul(a, b, m) << '\n';
    }
    return 0;
}

