#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    if (!getline(cin, s)) return 0;
    int n = (int)s.size(), bl = 0, br = -1;  // 最优区间 [bl, br]
    auto expand = [&](int l, int r) {
        while (l >= 0 && r < n && s[l] == s[r]) { --l; ++r; }
        // 回文是 (l, r) 开区间，即 [l+1, r-1]
        if (r - l - 1 > br - bl + 1) { bl = l + 1; br = r - 1; }
    };
    for (int c = 0; c < n; ++c) {
        expand(c, c);      // 奇回文
        expand(c, c + 1);  // 偶回文
    }
    cout << s.substr(bl, br - bl + 1) << '\n';
    return 0;
}

