// 返回 a 中最大的 k 个数（降序）
vector<int> topk_largest(vector<int> a, int k) {
    priority_queue<int> pq(a.begin(), a.end());
    vector<int> res;
    for (int i = 0; i < k && !pq.empty(); ++i) {
        res.push_back(pq.top());
        pq.pop();
    }
    return res;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<int> a(n);
