def edit_distance(a, b):
    '''返回把 a 变成 b 的最少编辑操作数（插入/删除/替换）。'''
    m, n = len(a), len(b)
    prev = list(range(n + 1))  # 空串变 b 前 j 个要插 j 次
    for i in range(1, m + 1):
        cur = [i] + [0] * n    # a 前 i 个变空串要删 i 次
        ai = a[i - 1]
        for j in range(1, n + 1):
            if ai == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j], cur[j - 1], prev[j - 1])
        prev = cur
    return prev[n]


if __name__ == '__main__':
