#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
// 不限交易次数，求最大利润
int64 max_profit(const vector<int64> &prices) {
    const int64 NEG = (int64)-4e18;
    int64 hold = NEG, cash = 0;
    for (int64 p : prices) {
        hold = max(hold, -p);
        cash = max(cash, hold + p);
    }
    return cash;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int64> prices(n);
    for (int i = 0; i < n; ++i) cin >> prices[i];
    cout << max_profit(prices) << '\n';
    return 0;
}

