#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
// 多重背包：二进制拆分转 01 背包
int64 bounded_knapsack(const vector<array<int64, 3>> &items, int64 W) {
    vector<pair<int64, int64>> objs;
    for (auto it : items) {
        int64 w = it[0], v = it[1], k = it[2], t = 1;
        while (k > 0) {
            int64 c = min(t, k);
            objs.emplace_back(w * c, v * c);
            k -= c;
            t <<= 1;
        }
    }
    vector<int64> dp(W + 1, 0);
    for (auto [w, v] : objs)
        for (int64 j = W; j >= w; --j)
            dp[j] = max(dp[j], dp[j - w] + v);
    return *max_element(dp.begin(), dp.end());
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    int64 W;
    if (!(cin >> n >> W)) return 0;
    vector<array<int64, 3>> items(n);
    for (int i = 0; i < n; ++i) cin >> items[i][0] >> items[i][1] >> items[i][2];
    cout << bounded_knapsack(items, W) << '\n';
    return 0;
}

