def count_paths(grid):
    '''只能向右/向下走，1 是障碍；返回路径数对 1e9+7 取模。'''
    m, n = len(grid), len(grid[0])
    dp = [0] * n
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[j] = 0
            elif i == 0 and j == 0:
                dp[j] = 1
            elif j == 0:
                pass  # dp[j] 保持上一行的值
            else:
                dp[j] = (dp[j] + dp[j - 1]) % MOD
    return dp[n - 1]


