#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int64 MOD = 1000000007LL;
// 只能向右/向下走，1 是障碍；返回路径数对 1e9+7 取模
int64 count_paths(const vector<vector<int>> &g) {
    int m = g.size(), n = g[0].size();
    vector<int64> dp(n, 0);
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < n; ++j) {
            if (g[i][j] == 1) dp[j] = 0;
            else if (i == 0 && j == 0) dp[j] = 1;
            else if (j == 0) { /* dp[j] 保持上一行的值 */ }
            else dp[j] = (dp[j] + dp[j - 1]) % MOD;
        }
    return dp[n - 1];
}
int main() {
