    vector<vector<int>> g(m, vector<int>(n));
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < n; ++j) cin >> g[i][j];
    cout << count_paths(g) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
// 归并排序求逆序对数，返回 {排好序的数组, 逆序对数}
pair<vector<int64>, int64> sort_count(vector<int64> a) {
    int64 n = (int64)a.size();
    if (n <= 1) return {a, 0};
    int64 mid = n / 2;
    vector<int64> left(a.begin(), a.begin() + mid);
    vector<int64> right(a.begin() + mid, a.end());
    auto pl = sort_count(move(left));
    auto pr = sort_count(move(right));
    vector<int64> &sl = pl.first, &sr = pr.first;
    vector<int64> merged;
    merged.reserve(n);
    int64 i = 0, j = 0, c = pl.second + pr.second;
    while (i < (int64)sl.size() && j < (int64)sr.size()) {
        if (sl[i] <= sr[j]) merged.push_back(sl[i++]);
        else {
            merged.push_back(sr[j++]);
            c += (int64)sl.size() - i;  // 左半剩余的都比它大
        }
    }
    while (i < (int64)sl.size()) merged.push_back(sl[i++]);
    while (j < (int64)sr.size()) merged.push_back(sr[j++]);
    return {merged, c};
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int64> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    cout << sort_count(a).second << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
// 单点加、区间求和。下标 0-based，查询区间 [l, r)
struct SegTree {
    int n;
    vector<int64> t;
    SegTree(const vector<int64> &a = {}) { init(a); }
    void init(const vector<int64> &a) {
        int sz = (int)a.size();
        n = 1;
        while (n < sz) n <<= 1;
        t.assign(2 * n, 0);
        for (int i = 0; i < sz; ++i) t[n + i] = a[i];
        for (int i = n - 1; i > 0; --i) t[i] = t[i << 1] + t[i << 1 | 1];
    }
    void add(int pos, int64 delta) {
        int i = n + pos;
        t[i] += delta;
        for (i >>= 1; i; i >>= 1) t[i] = t[i << 1] + t[i << 1 | 1];
    }
    int64 query(int l, int r) {  // [l, r)
        int64 res = 0;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res += t[l++];
            if (r & 1) res += t[--r];
        }
        return res;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    if (!(cin >> n >> q)) return 0;
    vector<int64> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    SegTree st(a);
    for (int k = 0; k < q; ++k) {
        int typ;
        cin >> typ;
        if (typ == 1) {          // 单点加：1 i x 表示 a[i] += x（1-based）
            int i;
            int64 x;
            cin >> i >> x;
            st.add(i - 1, x);
        } else {                 // 区间求和：2 l r（1-based 闭区间）
            int l, r;
            cin >> l >> r;
            cout << st.query(l - 1, r) << '\n';
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
// 静态区间最大值：O(n log n) 预处理，O(1) 查询
struct SparseTable {
    int n, LOG;
    vector<vector<int>> st;
    vector<int> lg;
    SparseTable(const vector<int> &a = {}) { init(a); }
    void init(const vector<int> &a) {
        n = (int)a.size();
        LOG = 1;
        while ((1 << LOG) <= n) ++LOG;
        st.assign(LOG, vector<int>(n));
        st[0] = a;
        for (int k = 1; k < LOG; ++k)
            for (int i = 0; i + (1 << k) <= n; ++i)
                st[k][i] = max(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
        lg.assign(n + 1, 0);
        for (int i = 2; i <= n; ++i) lg[i] = lg[i >> 1] + 1;
    }
    int query(int l, int r) const {  // [l, r) 0-based
        int k = lg[r - l];
        return max(st[k][l], st[k][r - (1 << k)]);
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    if (!(cin >> n >> q)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    SparseTable sp(a);
    for (int k = 0; k < q; ++k) {
        int l, r;  // 1-based 闭区间
        cin >> l >> r;
        cout << sp.query(l - 1, r) << '\n';
    }
    return 0;
}
